 5→
 6→public class BoxCollider(Rectangle bounds, HashSet<int> activeLayers = null, bool passive = false, bool enabled = true) : ICollider
 7→{
 8→    public Rectangle Bounds = bounds;
 9→    public HashSet<int> ActiveLayers { get; set; } = activeLayers ?? [-1];
