 1→using System;
 2→using System.Collections.Generic;
 3→using Microsoft.Xna.Framework;
 4→using MonoDreams.Extensions.Monogame;
 5→
 6→namespace MonoDreams.Component.Collision;
 7→
 8→/// <summary>
 9→/// Convex polygon collider defined by an ordered set of vertices (clockwise winding).
10→/// ModelVertices are in local space; WorldVertices are updated each frame by the detection system.
11→/// BroadPhaseAABB is recomputed from WorldVertices for fast rejection before SAT.
12→/// </summary>
13→public class ConvexCollider : ICollider
14→{
15→    /// <summary>Local-space vertices defining the convex polygon shape (clockwise winding).</summary>
16→    public Vector2[] ModelVertices;
17→
18→    /// <summary>Pre-allocated world-space vertices, updated each frame from ModelVertices + Transform.</summary>
19→    public Vector2[] WorldVertices;
20→
21→    /// <summary>AABB computed from WorldVertices for broad-phase rejection.</summary>
22→    public CollisionRect BroadPhaseAABB;
23→
24→    /// <summary>
25→    /// When true, UpdateWorldVertices ignores Transform.Rotation (treats it as 0).
26→    /// Used for colliders whose rotation is baked into ModelVertices (e.g. imported from Blender).
27→    /// </summary>
28→    public bool IgnoreTransformRotation;
29→
30→    public HashSet<int> ActiveLayers { get; set; }
31→    public bool Passive { get; set; }
32→    public bool Enabled { get; set; }
33→
34→    public ConvexCollider(Vector2[] modelVertices, HashSet<int> activeLayers = null, bool passive = false,
35→        bool enabled = true, bool ignoreTransformRotation = false)
36→    {
37→        if (modelVertices == null || modelVertices.Length < 3)
38→            throw new ArgumentException("ConvexCollider requires at least 3 vertices.", nameof(modelVertices));
39→
40→        ModelVertices = modelVertices;
41→        WorldVertices = new Vector2[modelVertices.Length];
42→        Array.Copy(modelVertices, WorldVertices, modelVertices.Length);
43→        BroadPhaseAABB = SATCollision.ComputeAABB(WorldVertices);
44→        ActiveLayers = activeLayers ?? [-1];
45→        Passive = passive;
46→        Enabled = enabled;
47→        IgnoreTransformRotation = ignoreTransformRotation;
48→    }
49→
50→    /// <summary>
51→    /// Transforms ModelVertices into WorldVertices using the entity's position, rotation, and scale.
52→    /// Recomputes BroadPhaseAABB afterward.
53→    /// </summary>
54→    public void UpdateWorldVertices(Transform transform)
55→    {
56→        var pos = transform.Position;
57→        var rot = IgnoreTransformRotation ? 0f : transform.Rotation;
58→        var scale = transform.Scale;
59→        var cos = MathF.Cos(rot);
60→        var sin = MathF.Sin(rot);
61→
62→        for (var i = 0; i < ModelVertices.Length; i++)
63→        {
64→            var v = ModelVertices[i];
65→            // Scale, then rotate, then translate
66→            var sx = v.X * scale.X;
67→            var sy = v.Y * scale.Y;
68→            WorldVertices[i] = new Vector2(
69→                sx * cos - sy * sin + pos.X,
70→                sx * sin + sy * cos + pos.Y);
71→        }
72→
73→        BroadPhaseAABB = SATCollision.ComputeAABB(WorldVertices);
74→    }
75→}
76→

 1→using System.Collections.Generic;
 2→using System.Linq;
 3→
 4→namespace MonoDreams.Component.Collision;
 5→
 6→public interface ICollider
 7→{
 8→    HashSet<int> ActiveLayers { get; set; }
 9→    public bool Passive { get; set; }
10→    public bool Enabled { get; set; }
11→    
12→    public bool SharesLayerWith(ICollider other) =>
13→        (ActiveLayers.Contains(-1) && other.ActiveLayers.Count > 0)
14→        || (other.ActiveLayers.Contains(-1) && ActiveLayers.Count > 0)
15→        || ActiveLayers.Overlaps(other.ActiveLayers);
16→
17→    public IEnumerable<int> SharedLayers(ICollider other)
18→    {
19→        if (ActiveLayers.Contains(-1) && other.ActiveLayers.Count > 0) return other.ActiveLayers;
20→        if (other.ActiveLayers.Contains(-1) && ActiveLayers.Count > 0) return ActiveLayers;
21→        return ActiveLayers.Intersect(other.ActiveLayers);
22→    }
23→}

 1→using Microsoft.Xna.Framework;
