 11→namespace MonoDreams.System.Debug;
 12→
 13→/// <summary>
 14→/// Debug system that renders collision shapes for entities with BoxCollider or ConvexCollider components.
 15→/// Shows green lines for passive colliders and red lines for active colliders.
 16→/// Only adds debug visuals when a collider is added to an entity.
 17→/// </summary>
 18→public sealed class ColliderDebugSystem : ISystem<GameState>
 19→{
 20→    private readonly World _world;
 21→    private readonly Texture2D _pixelTexture;
 22→    private const float DEBUG_LINE_DEPTH = 1f; // Render on top of all elements
 23→
 24→    public bool IsEnabled { get; set; } = true;
 25→
 26→    public ColliderDebugSystem(World world, GraphicsDevice graphicsDevice)
 27→    {
 28→        _world = world;
 29→        // Create a 2x1 white and transparent pixels texture for drawing lines
 30→        _pixelTexture = new Texture2D(graphicsDevice, 2, 1);
 31→        _pixelTexture.SetData([Color.White, Color.Transparent]);
 32→
 33→        _world.SubscribeEntityComponentAdded<BoxCollider>(AddDebugLinesToEntity);
 34→        _world.SubscribeEntityComponentAdded<ConvexCollider>(AddDebugLinesToConvexEntity);
 35→    }
 36→
 37→    private void AddDebugLinesToEntity(in Entity entity, in BoxCollider boxCollider)
 38→    {
 39→        var size = boxCollider.Bounds.Dimension();
 40→        if (size.X <= 0 || size.Y <= 0)
 41→            return;
 42→
 43→        ref readonly var transform = ref entity.Get<Transform>();
 44→        var lineColor = GetDebugColor(boxCollider);
 45→        var r = new Rectangle(0, 0, 1, 1);
 46→        var c = new Rectangle(1, 0, 1, 1);
 47→        var spriteInfo = new SpriteInfo{
 48→            SpriteSheet = _pixelTexture,
 49→            Source = new Rectangle(0, 0, 1, 1),
 50→            Size = boxCollider.Bounds.Dimension(),
 51→            Color = lineColor,
 52→            Target = RenderTargetID.Main,
 53→            LayerDepth = DEBUG_LINE_DEPTH,
 54→            NinePatchData = new NinePatchInfo(0, r, r, r, r, c, r, r, r, r),
 55→            Offset = boxCollider.Bounds.Origin(),
 56→        };
 57→
 58→        var debugEntity = _world.CreateEntity();
 59→        debugEntity.Set(transform);
 60→        debugEntity.Set(spriteInfo);
 61→        debugEntity.Set(new DrawComponent());
 62→    }
 63→
 64→    private void AddDebugLinesToConvexEntity(in Entity entity, in ConvexCollider convexCollider)
 65→    {
 66→        // Use the broad-phase AABB as a debug outline for convex colliders
 67→        var aabb = SATCollision.ComputeAABB(convexCollider.ModelVertices);
 68→        if (aabb.Size.X <= 0 || aabb.Size.Y <= 0)
 69→            return;
 70→
 71→        ref readonly var transform = ref entity.Get<Transform>();
 72→        var lineColor = GetDebugColor(convexCollider);
 73→
 74→        var r = new Rectangle(0, 0, 1, 1);
 75→        var c = new Rectangle(1, 0, 1, 1);
 76→        var spriteInfo = new SpriteInfo{
 77→            SpriteSheet = _pixelTexture,
 78→            Source = new Rectangle(0, 0, 1, 1),
 79→            Size = aabb.Size,
 80→            Color = lineColor,
 81→            Target = RenderTargetID.Main,
 82→            LayerDepth = DEBUG_LINE_DEPTH,
 83→            NinePatchData = new NinePatchInfo(0, r, r, r, r, c, r, r, r, r),
 84→            Offset = aabb.Position,
 85→        };
 86→
 87→        var debugEntity = _world.CreateEntity();
 88→        debugEntity.Set(transform);
 89→        debugEntity.Set(spriteInfo);
 90→        debugEntity.Set(new DrawComponent());
 91→    }
 92→
 93→    private static Color GetDebugColor(ICollider collider)
 94→    {
 95→        if (!collider.Enabled) return Color.Gray;
 96→        return collider.Passive ? Color.Green : Color.Red;
 97→    }
 98→
 99→    private void AddDebugLine(DrawComponent drawComponent, int x1, int y1, int x2, int y2, Color color)
100→    {
101→        // Calculate line properties
102→        var start = new Vector2(x1, y1);
103→        var end = new Vector2(x2, y2);
104→        var direction = end - start;
105→        var length = direction.Length();
106→        var size = x1 == x2 ? new Vector2(1, length) : new Vector2(length, 1);
107→
108→        // Create a DrawElement for the line
109→        var lineElement = new DrawElement
110→        {
111→            Type = DrawElementType.Sprite,
112→            Target = RenderTargetID.Main,
113→            Texture = _pixelTexture,
114→            Position = start,
115→            Size = size,
116→            Color = color,
117→            LayerDepth = DEBUG_LINE_DEPTH,
118→        };
119→
120→        // drawComponent.Drawables.Add(lineElement);
121→    }
122→
123→    public void Update(GameState state)
124→    {
125→        // This system doesn't need to update every frame since it only responds to entity changes
126→        // The work is done in the EntityAdded event handler
127→    }
128→
129→    public void Dispose()
130→    {
131→        _pixelTexture?.Dispose();
132→    }
133→}
