  1→using System;
  2→using System.Collections.Generic;
  3→using DefaultEcs;
  4→using DefaultEcs.System;
  5→using Microsoft.Xna.Framework;
  6→using Microsoft.Xna.Framework.Graphics;
  7→using MonoDreams.Component;
  8→using MonoDreams.Component.Draw;
  9→using MonoDreams.State;
 10→
 11→namespace MonoDreams.System.Debug;
 12→
 13→/// <summary>
 14→/// Debug visualization system for sprite rendering.
 15→/// Renders semi-transparent rectangles showing sprite boundaries and yellow circles at origin points.
 16→/// </summary>
 17→public class SpriteDebugSystem : ISystem<GameState>
 18→{
 19→    /// <summary>
 20→    /// Global toggle for sprite debug visualization.
 21→    /// </summary>
 22→    public static bool Enabled = true;
 23→
 24→    private const float DebugLayerDepth = 0.98f;
 25→    private const float OriginCircleRadius = 0.2f;
 26→    private const int CircleSegments = 12;
 27→    private const float LineThickness = 0.1f;
 28→
 29→    private readonly World _world;
 30→    private readonly EntitySet _spriteEntities;
 31→    private readonly RenderTargetID _renderTarget;
 32→
 33→    // Track debug entities for cleanup
 34→    private readonly List<Entity> _debugEntities = [];
 35→
 36→    // Colors
 37→    private static readonly Color BoundsColor = new(0, 0, 0, 50);
 38→    private static readonly Color OriginColor = Color.Orange;
 39→
 40→    public SpriteDebugSystem(World world, RenderTargetID renderTarget = RenderTargetID.Main)
 41→    {
 42→        _world = world;
 43→        _renderTarget = renderTarget;
 44→
 45→        _spriteEntities = world.GetEntities()
 46→            .With<DrawComponent>()
 47→            .With<SpriteInfo>()
 48→            .With<Transform>()
 49→            .AsSet();
 50→    }
 51→
 52→    public bool IsEnabled { get; set; } = true;
 53→
 54→    public void Update(GameState state)
 55→    {
 56→        // Clean up old debug entities
 57→        foreach (var entity in _debugEntities)
 58→        {
 59→            if (entity.IsAlive)
 60→            {
 61→                entity.Dispose();
 62→            }
 63→        }
 64→        _debugEntities.Clear();
 65→
 66→        if (!IsEnabled || !Enabled) return;
 67→
 68→        // Create debug visuals for each sprite entity
 69→        foreach (var entity in _spriteEntities.GetEntities())
 70→        {
 71→            ref readonly var drawComponent = ref entity.Get<DrawComponent>();
 72→
 73→            // Only visualize sprite types
 74→            if (drawComponent.Type != DrawElementType.Sprite) continue;
 75→            if (drawComponent.Size == Vector2.Zero) continue;
 76→
 77→            // Get the position and origin from DrawComponent
 78→            var position = drawComponent.Position;
 79→            var origin = drawComponent.Origin;
 80→            var size = drawComponent.Size;
 81→
 82→            // Calculate the top-left corner of the sprite bounds
 83→            // Origin is in SOURCE texture coordinates, so we need to scale it to destination size
 84→            // scale = destinationSize / sourceSize
 85→            Vector2 scaledOrigin;
 86→            if (drawComponent.SourceRectangle.HasValue &&
 87→                drawComponent.SourceRectangle.Value.Width > 0 &&
 88→                drawComponent.SourceRectangle.Value.Height > 0)
 89→            {
 90→                scaledOrigin = new Vector2(
 91→                    origin.X * size.X / drawComponent.SourceRectangle.Value.Width,
 92→                    origin.Y * size.Y / drawComponent.SourceRectangle.Value.Height);
 93→            }
 94→            else
 95→            {
 96→                scaledOrigin = origin;
 97→            }
 98→
 99→            // When rendering, SpriteBatch places the scaled origin at position
100→            // So bounds top-left = position - scaledOrigin
101→            var boundsTopLeft = position - scaledOrigin;
102→
103→            // Create bounds rectangle (semi-transparent black)
104→            CreateFilledRectEntity(boundsTopLeft.X, boundsTopLeft.Y, size.X, size.Y, BoundsColor);
105→
106→            // Create origin circle (yellow) at the position
107→            CreateCircleEntity(position.X, position.Y, OriginCircleRadius, OriginColor);
108→
109→            // Create line from origin to center of bounds
110→            var boundsCenter = boundsTopLeft + size / 2;
111→            CreateLineEntity(position, boundsCenter, OriginColor);
112→        }
113→    }
114→
115→    private void CreateFilledRectEntity(float x, float y, float width, float height, Color color)
116→    {
117→        var entity = _world.CreateEntity();
118→        _debugEntities.Add(entity);
119→
120→        // Create a filled rectangle with 4 vertices and 2 triangles
121→        var vertices = new VertexPositionColor[]
122→        {
123→            new(new Vector3(x, y, 0), color),                         // Top-left
124→            new(new Vector3(x + width, y, 0), color),                 // Top-right
125→            new(new Vector3(x + width, y + height, 0), color),        // Bottom-right
126→            new(new Vector3(x, y + height, 0), color),                // Bottom-left
127→        };
128→
129→        var indices = new int[]
130→        {
131→            0, 1, 2,  // First triangle
132→            0, 2, 3   // Second triangle
133→        };
134→
135→        entity.Set(new DrawComponent
136→        {
137→            Type = DrawElementType.Mesh,
138→            Vertices = vertices,
139→            Indices = indices,
140→            PrimitiveType = PrimitiveType.TriangleList,
141→            Target = _renderTarget,
142→            LayerDepth = DebugLayerDepth
143→        });
144→    }
145→
146→    private void CreateCircleEntity(float centerX, float centerY, float radius, Color color)
147→    {
148→        var entity = _world.CreateEntity();
149→        _debugEntities.Add(entity);
150→
151→        // Create a filled circle using triangle fan
152→        var vertices = new List<VertexPositionColor>();
153→        var indices = new List<int>();
154→
155→        // Center vertex
156→        vertices.Add(new VertexPositionColor(new Vector3(centerX, centerY, 0), color));
157→
158→        // Perimeter vertices
159→        for (int i = 0; i <= CircleSegments; i++)
160→        {
161→            var angle = (float)(i * 2 * Math.PI / CircleSegments);
162→            var px = centerX + radius * MathF.Cos(angle);
163→            var py = centerY + radius * MathF.Sin(angle);
164→            vertices.Add(new VertexPositionColor(new Vector3(px, py, 0), color));
165→        }
166→
167→        // Create triangles (triangle fan from center)
168→        for (int i = 1; i <= CircleSegments; i++)
169→        {
170→            indices.Add(0);       // Center
171→            indices.Add(i);       // Current perimeter vertex
172→            indices.Add(i + 1);   // Next perimeter vertex
173→        }
174→
175→        entity.Set(new DrawComponent
176→        {
177→            Type = DrawElementType.Mesh,
178→            Vertices = vertices.ToArray(),
179→            Indices = indices.ToArray(),
180→            PrimitiveType = PrimitiveType.TriangleList,
181→            Target = _renderTarget,
182→            LayerDepth = DebugLayerDepth + 0.001f  // Slightly in front of bounds
183→        });
184→    }
185→
186→    private void CreateLineEntity(Vector2 start, Vector2 end, Color color)
187→    {
188→        var entity = _world.CreateEntity();
189→        _debugEntities.Add(entity);
190→
191→        // Calculate perpendicular direction for line thickness
192→        var direction = end - start;
193→        if (direction.LengthSquared() < 0.0001f) return;
194→
195→        var perpendicular = new Vector2(-direction.Y, direction.X);
196→        perpendicular.Normalize();
197→        perpendicular *= LineThickness / 2;
198→
199→        // Create a quad (thick line) with 4 vertices
200→        var vertices = new VertexPositionColor[]
201→        {
202→            new(new Vector3(start + perpendicular, 0), color),
203→            new(new Vector3(start - perpendicular, 0), color),
204→            new(new Vector3(end - perpendicular, 0), color),
205→            new(new Vector3(end + perpendicular, 0), color),
206→        };
207→
208→        var indices = new int[]
209→        {
210→            0, 1, 2,
211→            0, 2, 3
212→        };
213→
214→        entity.Set(new DrawComponent
215→        {
216→            Type = DrawElementType.Mesh,
217→            Vertices = vertices,
218→            Indices = indices,
219→            PrimitiveType = PrimitiveType.TriangleList,
220→            Target = _renderTarget,
221→            LayerDepth = DebugLayerDepth + 0.0005f  // Between bounds and circle
222→        });
223→    }
224→
225→    public void Dispose()
226→    {
227→        foreach (var entity in _debugEntities)
228→        {
229→            if (entity.IsAlive)
230→            {
231→                entity.Dispose();
232→            }
233→        }
234→        _debugEntities.Clear();
235→        _spriteEntities.Dispose();
236→    }
237→}
