  1→using System;
  2→using System.Runtime.InteropServices.Marshalling;
  3→using Microsoft.Xna.Framework;
  4→
  5→namespace MonoDreams.Component;
  6→
  7→public class Camera
  8→{
  9→    private float _zoom;
 10→    private float _rotation;
 11→    private Vector2 _position;
 12→    private Matrix _transform = Matrix.Identity;
 13→    private bool _isViewTransformationDirty = true;
 14→    private Matrix _camTranslationMatrix = Matrix.Identity;
 15→    private Matrix _camRotationMatrix = Matrix.Identity;
 16→    private Matrix _camScaleMatrix = Matrix.Identity;
 17→    private Matrix _resTranslationMatrix = Matrix.Identity;
 18→
 19→    private Vector3 _camTranslationVector = Vector3.Zero;
 20→    private Vector3 _camScaleVector = Vector3.Zero;
 21→    private Vector3 _resTranslationVector = Vector3.Zero;
 22→
 23→    private (float zoom, Vector2 cached) _viewSize = (float.NaN, Vector2.Zero);
 24→    private (Vector2 position, Vector2 viewSize, Rectangle cached) _virtualScreenBounds;
 25→    
 26→    // Camera operates in virtual resolution space
 27→    private readonly int _virtualWidth;
 28→    private readonly int _virtualHeight;
 29→
 30→    public int VirtualWidth => _virtualWidth;
 31→    public int VirtualHeight => _virtualHeight;
 32→
 33→    public Camera(int virtualWidth = 800, int virtualHeight = 600) // Use configured virtual size
 34→    {
 35→        _virtualWidth = virtualWidth;
 36→        _virtualHeight = virtualHeight;
 37→        _zoom = 1.0f;
 38→        _rotation = 0.0f;
 39→        _position = Vector2.Zero;
 40→    }
 41→
 42→    public Vector2 ViewSize
 43→    {
 44→        get {
 45→            if (_viewSize.zoom != _zoom)
 46→            {
 47→                _viewSize = (_zoom, new Vector2(_virtualWidth / _zoom, _virtualHeight / _zoom));
 48→            }
 49→            return _viewSize.cached;
 50→        }
 51→    }
 52→
 53→    public Vector2 Position
 54→    {
 55→        get => _position;
 56→        set
 57→        {
 58→            _position = value;
 59→            _isViewTransformationDirty = true;
 60→        }
 61→    }
 62→
 63→    public float Zoom
 64→    {
 65→        get => _zoom;
 66→        set
 67→        {
 68→            _zoom = value;
 69→            if (_zoom < 0.1f)
 70→            {
 71→                _zoom = 0.1f;
 72→            }
 73→            _isViewTransformationDirty = true;
 74→        }
 75→    }
 76→
 77→    public float Rotation
 78→    {
 79→        get => _rotation;
 80→        set
 81→        {
 82→            _rotation = value;
 83→            _isViewTransformationDirty = true;
 84→        }
 85→    }
 86→
 87→    public Rectangle VirtualScreenBounds
 88→    {
 89→        get
 90→        {
 91→            if (_virtualScreenBounds.position != Position || _virtualScreenBounds.viewSize != ViewSize)
 92→            {
 93→                var bounds = new Rectangle( new Point((int)(Position.X - ViewSize.X * 0.5f), (int)(Position.Y - ViewSize.Y * 0.5f)), ViewSize.ToPoint());
 94→                _virtualScreenBounds = (Position, ViewSize, bounds);
 95→            }
 96→            return _virtualScreenBounds.cached;
 97→        }
 98→    }
 99→
100→    public Matrix GetViewTransformationMatrix()
101→    {
102→        if (!_isViewTransformationDirty) return _transform;
103→        
104→        _camTranslationVector.X = -_position.X;
105→        _camTranslationVector.Y = -_position.Y;
106→
107→        Matrix.CreateTranslation(ref _camTranslationVector, out _camTranslationMatrix);
108→        Matrix.CreateRotationZ(_rotation, out _camRotationMatrix);
109→
110→        _camScaleVector.X = _zoom;
111→        _camScaleVector.Y = _zoom;
112→        _camScaleVector.Z = 1;
113→
114→        Matrix.CreateScale(ref _camScaleVector, out _camScaleMatrix);
115→
116→        // Translate origin to center of the virtual screen for rotation/zoom
117→        _resTranslationVector.X = _virtualWidth * 0.5f;
118→        _resTranslationVector.Y = _virtualHeight * 0.5f;
119→        _resTranslationVector.Z = 0;
120→
121→        Matrix.CreateTranslation(ref _resTranslationVector, out _resTranslationMatrix);
122→
123→        _transform = _camTranslationMatrix 
124→                     * _camRotationMatrix
125→                     * _camScaleMatrix
126→                     * _resTranslationMatrix;
127→
128→        _isViewTransformationDirty = false;
129→
130→        return _transform;
131→    }
132→
133→    public void RecalculateTransformationMatrices()
134→    {
135→        _isViewTransformationDirty = true;
136→    }
137→
138→    /// <summary>
139→    /// Converts virtual screen coordinates (e.g., mouse position scaled to virtual resolution)
140→    /// to world coordinates.
141→    /// </summary>
142→    /// <param name="virtualScreenPosition">Coordinates in the virtual screen space (0,0 to VirtualWidth, VirtualHeight).</param>
143→    /// <returns>World coordinates.</returns>
144→    public Vector2 VirtualScreenToWorld(Vector2 virtualScreenPosition)
145→    {
146→        Matrix invViewMatrix = Matrix.Invert(GetViewTransformationMatrix());
147→        return Vector2.Transform(virtualScreenPosition, invViewMatrix);
148→    }
149→}

  1→#nullable enable
  2→using Microsoft.Xna.Framework;
  3→
  4→namespace MonoDreams.Component;
  5→
  6→/// <summary>
  7→/// Represents the spatial transformation of an entity including position, rotation, scale, and origin.
  8→/// Supports parent-child hierarchies where transforms are relative to a parent transform.
  9→/// Extends the concept of Position with full transform capabilities.
 10→/// </summary>
 11→public class Transform
 12→{
 13→    // Backing fields
 14→    private Vector2 _position;
 15→    private Vector2 _lastPosition;
 16→    private float _rotation;
 17→    private Vector2 _scale;
 18→    private Vector2 _origin;
 19→    private Transform? _parent;
 20→
 21→    // Cache for world transform calculations
 22→    private Matrix? _worldMatrix;
 23→    private bool _isDirty = true;
 24→
 25→    public Transform(Vector2 position = default, float rotation = 0f, Vector2? scale = null, Vector2? origin = null)
 26→    {
 27→        _position = position;
 28→        _lastPosition = position;
 29→        _rotation = rotation;
 30→        _scale = scale ?? Vector2.One;
 31→        _origin = origin ?? Vector2.Zero;
 32→    }
 33→
 34→    #region Properties with Auto-Dirty
 35→
 36→    /// <summary>
 37→    /// Local position (relative to parent if Parent is set, otherwise world position).
 38→    /// Setting this property automatically marks the transform as dirty.
 39→    /// </summary>
 40→    public Vector2 Position
 41→    {
 42→        get => _position;
 43→        set { _position = value; SetDirty(); }
 44→    }
 45→
 46→    /// <summary>
 47→    /// Position from the previous frame. Used for delta calculations.
 48→    /// Does NOT mark the transform as dirty when set.
 49→    /// </summary>
 50→    public Vector2 LastPosition
 51→    {
 52→        get => _lastPosition;
 53→        set => _lastPosition = value;
 54→    }
 55→
 56→    /// <summary>
 57→    /// Local rotation in radians.
 58→    /// Setting this property automatically marks the transform as dirty.
 59→    /// </summary>
 60→    public float Rotation
 61→    {
 62→        get => _rotation;
 63→        set { _rotation = value; SetDirty(); }
 64→    }
 65→
 66→    /// <summary>
 67→    /// Local scale.
 68→    /// Setting this property automatically marks the transform as dirty.
 69→    /// </summary>
 70→    public Vector2 Scale
 71→    {
 72→        get => _scale;
 73→        set { _scale = value; SetDirty(); }
 74→    }
 75→
 76→    /// <summary>
 77→    /// Origin/pivot point for rotation and scaling.
 78→    /// Setting this property automatically marks the transform as dirty.
 79→    /// </summary>
 80→    public Vector2 Origin
 81→    {
 82→        get => _origin;
 83→        set { _origin = value; SetDirty(); }
 84→    }
 85→
 86→    /// <summary>
 87→    /// Parent transform for hierarchical transforms.
 88→    /// Setting this property automatically marks the transform as dirty.
 89→    /// </summary>
 90→    public Transform? Parent
 91→    {
 92→        get => _parent;
 93→        set { _parent = value; SetDirty(); }
 94→    }
 95→
 96→    #endregion
 97→
 98→    public bool HasMoved => _position != _lastPosition;
 99→    public Vector2 Delta => _position - _lastPosition;
100→
101→    /// <summary>
102→    /// Gets whether this transform needs its world matrix recalculated.
103→    /// </summary>
104→    public bool IsDirty => _isDirty;
105→
106→    #region World Transform (Computed)
107→
108→    /// <summary>
109→    /// Gets the world transformation matrix, combining this transform with its parent chain.
110→    /// The matrix includes origin offset, scale, rotation, and translation.
111→    /// </summary>
112→    public Matrix WorldMatrix
113→    {
114→        get
115→        {
116→            // Check if this transform is dirty OR if parent is dirty
117→            var parentDirty = _parent != null && _parent._isDirty;
118→
119→            if (_isDirty || parentDirty || !_worldMatrix.HasValue)
120→            {
121→                // Build local matrix: Origin offset -> Scale -> Rotation -> Position
122→                var localMatrix =
123→                    Matrix.CreateTranslation(-_origin.X, -_origin.Y, 0) *
124→                    Matrix.CreateScale(_scale.X, _scale.Y, 1) *
125→                    Matrix.CreateRotationZ(_rotation) *
126→                    Matrix.CreateTranslation(_position.X, _position.Y, 0);
127→
128→                // Combine with parent's world matrix if parent exists
129→                _worldMatrix = _parent != null
130→                    ? localMatrix * _parent.WorldMatrix
131→                    : localMatrix;
132→
133→                _isDirty = false;
134→            }
135→
136→            return _worldMatrix.Value;
137→        }
138→    }
139→
140→    /// <summary>
141→    /// Gets the world position by extracting translation from the world matrix.
142→    /// </summary>
143→    public Vector2 WorldPosition
144→    {
145→        get
146→        {
147→            var matrix = WorldMatrix;
148→            return new Vector2(matrix.M41, matrix.M42);
149→        }
150→    }
151→
152→    /// <summary>
153→    /// Gets the world rotation by accumulating rotations up the parent chain.
154→    /// </summary>
155→    public float WorldRotation
156→    {
157→        get
158→        {
159→            return _parent != null
160→                ? _rotation + _parent.WorldRotation
161→                : _rotation;
162→        }
163→    }
164→
165→    /// <summary>
166→    /// Gets the world scale by multiplying scales up the parent chain.
167→    /// </summary>
168→    public Vector2 WorldScale
169→    {
170→        get
171→        {
172→            return _parent != null
173→                ? _scale * _parent.WorldScale
174→                : _scale;
175→        }
176→    }
177→
178→    #endregion
179→
180→    #region Methods
181→
182→    /// <summary>
183→    /// Marks this transform as dirty, forcing recalculation of the world matrix on next access.
184→    /// This is called automatically when properties are set, but can be called manually if needed.
185→    /// </summary>
186→    public void SetDirty()
187→    {
188→        _isDirty = true;
189→    }
190→
191→    /// <summary>
192→    /// Updates LastPosition to current. Call this at the end of each frame.
193→    /// </summary>
194→    public void CommitPosition()
195→    {
196→        _lastPosition = _position;
197→    }
198→
199→    #endregion
200→
201→    #region Fluent Position Methods
202→
203→    /// <summary>Sets the X component of position.</summary>
204→    public Transform SetPositionX(float x)
205→    {
206→        _position.X = x;
207→        SetDirty();
208→        return this;
209→    }
210→
211→    /// <summary>Sets the Y component of position.</summary>
212→    public Transform SetPositionY(float y)
213→    {
214→        _position.Y = y;
215→        SetDirty();
216→        return this;
217→    }
218→
219→    /// <summary>Adds a delta to position.</summary>
220→    public Transform Translate(Vector2 delta)
221→    {
222→        _position += delta;
223→        SetDirty();
224→        return this;
225→    }
226→
227→    /// <summary>Adds x and y deltas to position.</summary>
228→    public Transform Translate(float x, float y)
229→    {
230→        _position.X += x;
231→        _position.Y += y;
232→        SetDirty();
233→        return this;
234→    }
235→
236→    /// <summary>Adds a delta to the X component of position.</summary>
237→    public Transform TranslateX(float delta)
238→    {
239→        _position.X += delta;
240→        SetDirty();
241→        return this;
242→    }
243→
244→    /// <summary>Adds a delta to the Y component of position.</summary>
245→    public Transform TranslateY(float delta)
246→    {
247→        _position.Y += delta;
248→        SetDirty();
249→        return this;
250→    }
251→
252→    #endregion
253→
254→    #region Fluent Rotation Methods
255→
256→    /// <summary>Adds radians to rotation.</summary>
257→    public Transform Rotate(float radians)
258→    {
259→        _rotation += radians;
260→        SetDirty();
261→        return this;
262→    }
263→
264→    #endregion
265→
266→    #region Fluent Scale Methods
267→
268→    /// <summary>Sets the X component of scale.</summary>
269→    public Transform SetScaleX(float x)
270→    {
271→        _scale.X = x;
272→        SetDirty();
273→        return this;
274→    }
275→
276→    /// <summary>Sets the Y component of scale.</summary>
277→    public Transform SetScaleY(float y)
278→    {
279→        _scale.Y = y;
280→        SetDirty();
281→        return this;
282→    }
283→
284→    /// <summary>Sets uniform scale.</summary>
285→    public Transform SetScale(float uniform)
286→    {
287→        _scale = new Vector2(uniform, uniform);
288→        SetDirty();
289→        return this;
290→    }
291→
292→    /// <summary>Multiplies scale by a factor.</summary>
293→    public Transform ScaleBy(Vector2 factor)
294→    {
295→        _scale *= factor;
296→        SetDirty();
297→        return this;
298→    }
299→
300→    /// <summary>Multiplies scale uniformly by a factor.</summary>
301→    public Transform ScaleBy(float factor)
302→    {
303→        _scale *= factor;
304→        SetDirty();
305→        return this;
306→    }
307→
308→    #endregion
309→
310→    #region Fluent Origin Methods
311→
312→    /// <summary>Sets the X component of origin.</summary>
