 16→/// Uses ColliderTag marker component to query entities with either collider type.
 17→/// Runs single-threaded because instance-level polygon buffers (_boxPolyBufA/_boxPolyBufB)
 18→/// are not thread-safe.
 19→/// </summary>
 20→public class TransformCollisionDetectionSystem<TCollisionMessage> : ISystem<GameState>
 21→    where TCollisionMessage : ICollisionMessage
 22→{
 23→    private readonly World _world;
 24→    private readonly EntitySet _activeSet;
 25→    private readonly IEnumerable<Entity> _targets;
 26→    private readonly CreateCollisionMessageDelegate<TCollisionMessage> _createCollisionMessage;
 27→
 28→    public bool IsEnabled { get; set; } = true;
