 30→    public TransformCollisionDetectionSystem(
 31→        World world,
 32→        CreateCollisionMessageDelegate<TCollisionMessage> createCollisionMessage)
 33→    {
 34→        _world = world;
 35→        _createCollisionMessage = createCollisionMessage;
