 37→        // Auto-tag entities when they get a collider component
 38→        world.SubscribeEntityComponentAdded<BoxCollider>(OnBoxColliderAdded);
 39→        world.SubscribeEntityComponentAdded<ConvexCollider>(OnConvexColliderAdded);
 40→
 41→        // ColliderTag unifies BoxCollider and ConvexCollider into a single query, but each
 42→        // type has its own passive/enabled semantics — those are checked at runtime in the
 43→        // collision loop via GetCollider() rather than at query level.
 44→        _activeSet = world.GetEntities()
 45→            .With<ColliderTag>()
 46→            .With<Transform>()
 47→            .AsSet();
 48→
 49→        // All enabled collider entities are potential targets
 50→        _targets = world.GetEntities()
 51→            .With<ColliderTag>()
 52→            .With<Transform>()
 53→            .AsEnumerable();
 54→    }
