 57→    {
 58→        if (!entity.Has<ColliderTag>()) entity.Set<ColliderTag>();
 59→    }
 60→
 61→    private static void OnConvexColliderAdded(in Entity entity, in ConvexCollider _)
 62→    {
 63→        if (!entity.Has<ColliderTag>()) entity.Set<ColliderTag>();
 64→    }
 65→
 66→    public void Update(GameState state)
 67→    {
 68→        // Update world vertices for all ConvexCollider entities (_targets is the superset of _activeSet)
 69→        foreach (var target in _targets)
 70→        {
 71→            if (target.Has<ConvexCollider>())
 72→            {
 73→                ref var convex = ref target.Get<ConvexCollider>();
 74→                convex.UpdateWorldVertices(target.Get<Transform>());
 75→            }
 76→        }
 77→
 78→        // Test collisions
 79→        foreach (var entity in _activeSet.GetEntities())
 80→        {
 81→            var colliderA = GetCollider(entity);
 82→            if (colliderA == null || colliderA.Passive || !colliderA.Enabled) continue;
 83→
 84→            foreach (var target in _targets)
 85→            {
 86→                if (target == entity) continue;
 87→
 88→                var colliderB = GetCollider(target);
 89→                if (colliderB == null || !colliderB.Enabled) continue;
 90→                if (!colliderB.SharesLayerWith(colliderA)) continue;
 91→
 92→                var hasBoxA = entity.Has<BoxCollider>();
 93→                var hasBoxB = target.Has<BoxCollider>();
 94→
 95→                if (hasBoxA && hasBoxB)
 96→                {
 97→                    // Box-vs-Box: existing swept AABB path (unchanged)
 98→                    TestBoxVsBox(entity, target, colliderA, colliderB);
 99→                }
