 84→/// <summary>
 85→/// Generates a line mesh with configurable thickness.
 86→/// </summary>
 87→public class LineMeshGenerator : IMeshGenerator
 88→{
 89→    public Vector2 Start { get; set; }
 90→    public Vector2 End { get; set; }
 91→    public float Thickness { get; set; }
 92→    public Color Color { get; set; }
 93→
 94→    public LineMeshGenerator(Vector2 start, Vector2 end, float thickness, Color color)
 95→    {
 96→        Start = start;
 97→        End = end;
 98→        Thickness = thickness;
 99→        Color = color;
100→    }
101→
102→    public MeshData Generate()
103→    {
104→        var vertices = new List<VertexPositionColor>();
105→        var indices = new List<int>();
106→        int indexOffset = 0;
107→
108→        AddLine(vertices, indices, Start, End, Thickness, Color, ref indexOffset);
109→
110→        return new MeshData(vertices.ToArray(), indices.ToArray());
111→    }
112→
113→    public static void AddLine(
114→        List<VertexPositionColor> vertices,
115→        List<int> indices,
116→        Vector2 start,
117→        Vector2 end,
118→        float thickness,
119→        Color color,
120→        ref int indexOffset)
121→    {
122→        Vector2 direction = end - start;
123→        Vector2 perpendicular = new(-direction.Y, direction.X);
124→        perpendicular.Normalize();
125→        perpendicular *= thickness / 2;
126→
127→        vertices.Add(new VertexPositionColor(new Vector3(start + perpendicular, 0), color));
128→        vertices.Add(new VertexPositionColor(new Vector3(start - perpendicular, 0), color));
129→        vertices.Add(new VertexPositionColor(new Vector3(end - perpendicular, 0), color));
130→        vertices.Add(new VertexPositionColor(new Vector3(end + perpendicular, 0), color));
131→
132→        indices.Add(indexOffset);
133→        indices.Add(indexOffset + 1);
134→        indices.Add(indexOffset + 2);
135→
136→        indices.Add(indexOffset);
137→        indices.Add(indexOffset + 2);
138→        indices.Add(indexOffset + 3);
139→
140→        indexOffset += 4;
141→    }
142→}
