147→public class RectangleOutlineMeshGenerator : IMeshGenerator
148→{
149→    public Rectangle Bounds { get; set; }
150→    public float Thickness { get; set; }
151→    public Color Color { get; set; }
152→
153→    public RectangleOutlineMeshGenerator(Rectangle bounds, float thickness, Color color)
154→    {
155→        Bounds = bounds;
156→        Thickness = thickness;
157→        Color = color;
158→    }
159→
160→    public MeshData Generate()
161→    {
162→        var vertices = new List<VertexPositionColor>();
163→        var indices = new List<int>();
164→        int indexOffset = 0;
165→
166→        var topLeft = new Vector2(Bounds.Left, Bounds.Top);
167→        var topRight = new Vector2(Bounds.Right, Bounds.Top);
168→        var bottomRight = new Vector2(Bounds.Right, Bounds.Bottom);
169→        var bottomLeft = new Vector2(Bounds.Left, Bounds.Bottom);
170→
171→        // Top edge
172→        LineMeshGenerator.AddLine(vertices, indices, topLeft, topRight, Thickness, Color, ref indexOffset);
173→        // Right edge
174→        LineMeshGenerator.AddLine(vertices, indices, topRight, bottomRight, Thickness, Color, ref indexOffset);
175→        // Bottom edge
176→        LineMeshGenerator.AddLine(vertices, indices, bottomRight, bottomLeft, Thickness, Color, ref indexOffset);
177→        // Left edge
178→        LineMeshGenerator.AddLine(vertices, indices, bottomLeft, topLeft, Thickness, Color, ref indexOffset);
179→
180→        return new MeshData(vertices.ToArray(), indices.ToArray());
