214→/// <summary>
215→/// Generates a gradient mesh along a path with configurable width and color function.
216→/// </summary>
217→public class GradientPathMeshGenerator : IMeshGenerator
218→{
219→    public Vector2[] PathPoints { get; set; }
220→    public float Width { get; set; }
221→    public Func<float, Color> ColorFunction { get; set; }
222→
223→    public GradientPathMeshGenerator(Vector2[] pathPoints, float width, Func<float, Color> colorFunction)
224→    {
225→        PathPoints = pathPoints;
226→        Width = width;
227→        ColorFunction = colorFunction;
228→    }
229→
230→    public MeshData Generate()
231→    {
232→        if (PathPoints == null || PathPoints.Length < 2)
233→            return new MeshData();
234→
235→        var vertices = new List<VertexPositionColor>();
236→        var indices = new List<int>();
237→
238→        for (int i = 0; i < PathPoints.Length; i++)
239→        {
240→            float t = (float)i / (PathPoints.Length - 1);
241→            var color = ColorFunction(t);
242→
243→            // Calculate perpendicular for width
244→            Vector2 direction;
245→            if (i == 0)
246→                direction = PathPoints[1] - PathPoints[0];
247→            else if (i == PathPoints.Length - 1)
248→                direction = PathPoints[i] - PathPoints[i - 1];
249→            else
250→                direction = PathPoints[i + 1] - PathPoints[i - 1];
251→
252→            direction.Normalize();
253→            var perpendicular = new Vector2(-direction.Y, direction.X) * (Width / 2);
254→
255→            vertices.Add(new VertexPositionColor(
256→                new Vector3(PathPoints[i] + perpendicular, 0), color));
257→            vertices.Add(new VertexPositionColor(
258→                new Vector3(PathPoints[i] - perpendicular, 0), color));
259→
260→            if (i > 0)
261→            {
262→                int baseIndex = (i - 1) * 2;
263→                indices.Add(baseIndex);
264→                indices.Add(baseIndex + 1);
265→                indices.Add(baseIndex + 2);
266→
267→                indices.Add(baseIndex + 1);
268→                indices.Add(baseIndex + 3);
269→                indices.Add(baseIndex + 2);
270→            }
271→        }
272→
273→        return new MeshData(vertices.ToArray(), indices.ToArray());
274→    }
275→}
