277→/// <summary>
278→/// Combines multiple mesh generators into a single mesh.
279→/// </summary>
280→public class CompositeMeshGenerator : IMeshGenerator
281→{
282→    private readonly List<IMeshGenerator> _generators = new();
283→
284→    public CompositeMeshGenerator Add(IMeshGenerator generator)
285→    {
286→        _generators.Add(generator);
287→        return this;
288→    }
289→
290→    public MeshData Generate()
291→    {
292→        var allVertices = new List<VertexPositionColor>();
293→        var allIndices = new List<int>();
294→
295→        foreach (var generator in _generators)
296→        {
297→            var mesh = generator.Generate();
298→            int indexOffset = allVertices.Count;
299→
300→            allVertices.AddRange(mesh.Vertices);
301→            foreach (var index in mesh.Indices)
302→            {
303→                allIndices.Add(index + indexOffset);
304→            }
305→        }
306→
307→        return new MeshData(allVertices.ToArray(), allIndices.ToArray());
308→    }
309→}
