14→public static class Logger
15→{
16→    private static readonly object Lock = new();
17→    private static StreamWriter _writer;
18→    private static LogLevel _minimumLevel = LogLevel.Debug;
19→    private static float _gameTime = -1f;
20→    private static bool _initialized;
21→
22→    public static void Initialize(string outputDirectory, LogLevel minimumLevel = LogLevel.Debug)
23→    {
24→        lock (Lock)
25→        {
26→            if (_initialized) return;
27→
28→            _minimumLevel = minimumLevel;
29→
30→            Directory.CreateDirectory(outputDirectory);
31→
32→            var timestamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
33→            var logPath = Path.Combine(outputDirectory, $"monodreams_{timestamp}.log");
34→            _writer = new StreamWriter(logPath, append: false) { AutoFlush = true };
35→            _initialized = true;
36→
37→            Info($"Logger initialized. Writing to {logPath}");
38→        }
39→    }
40→
41→    public static void UpdateGameTime(float totalTime)
42→    {
43→        _gameTime = totalTime;
44→    }
45→
46→    public static void Debug(string message) => Write(LogLevel.Debug, message);
47→    public static void Info(string message) => Write(LogLevel.Info, message);
48→    public static void Warning(string message) => Write(LogLevel.Warning, message);
49→    public static void Error(string message) => Write(LogLevel.Error, message);
50→
51→    public static void Shutdown()
52→    {
53→        lock (Lock)
54→        {
55→            if (!_initialized) return;
56→
57→            Info("Logger shutting down.");
58→            _writer?.Flush();
59→            _writer?.Dispose();
60→            _writer = null;
61→            _initialized = false;
62→            _gameTime = -1f;
63→        }
64→    }
65→
66→    private static void Write(LogLevel level, string message)
67→    {
68→        if (level < _minimumLevel) return;
69→
70→        var wallClock = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff");
71→        var gameTimeStr = _gameTime < 0 ? "  N/A " : $"{_gameTime,6:F2}";
72→        var levelStr = level switch
73→        {
74→            LogLevel.Debug => "DEBUG",
75→            LogLevel.Info => " INFO",
76→            LogLevel.Warning => " WARN",
77→            LogLevel.Error => "ERROR",
78→            _ => "?????",
79→        };
80→
81→        var line = $"[{wallClock}] [GT {gameTimeStr}] [{levelStr}] {message}";
82→
83→        lock (Lock)
84→        {
85→            Console.WriteLine(line);
86→            _writer?.WriteLine(line);
87→        }
88→    }
89→}
