218→{
219→    public Vector2[] PathPoints { get; set; }
220→    public float Width { get; set; }
221→    public Func<float, Color> ColorFunction { get; set; }
222→
223→    public GradientPathMeshGenerator(Vector2[] pathPoints, float width, Func<float, Color> colorFunction)
224→    {
225→        PathPoints = pathPoints;
226→        Width = width;
227→        ColorFunction = colorFunction;
228→    }
